const base = {
  internetMessageId: "<synthetic-outlook-001@example.test>",
  conversationId: "synthetic-outlook-conversation-001",
  receivedDateTime: "2026-10-22T08:15:00.000Z",
  subject: "Synthetic Outlook request",
  from: { emailAddress: { name: "Synthetic Sender", address: "alex@example.test" } },
  toRecipients: [{ emailAddress: { name: "Test Inbox", address: "inbox@example.test" } }],
  body: { contentType: "text", content: "Please review synthetic invoice INV-2030." },
  attachments: [{ id: "synthetic-attachment-001", name: "invoice.pdf", contentType: "application/pdf", size: 1234 }]
};
return [
  { ...base, id: "AAMkAGI2-synthetic-outlook-001" },
  { ...base, internetMessageId: "<synthetic-outlook-002@example.test>", id: "AAMkAGI2-synthetic-outlook-002", subject: "Second message in the same conversation" },
  { ...base, id: "AAMkAGI2-synthetic-outlook-001" }
].map((json, index) => ({ json, pairedItem: { item: index } }));

// shortcut: the fixed cutoff replays scoped-folder history on each poll, use a durable delta checkpoint when the test folder grows beyond a small test set.
const mode = $env.SMARTINBOX_OUTLOOK_MODE || "disabled";
if (mode === "disabled") return [];
if (mode !== "live") throw new Error("Set SMARTINBOX_OUTLOOK_MODE to disabled or live.");
const folderId = ($env.SMARTINBOX_OUTLOOK_TEST_FOLDER_ID || "").trim();
const reservedFolders = new Set(["inbox", "sentitems", "drafts", "deleteditems", "junkemail", "outbox", "archive"]);
if (!folderId || reservedFolders.has(folderId.toLowerCase())) throw new Error("Configure a dedicated Outlook test folder ID.");
const cutoff = new Date($env.SMARTINBOX_OUTLOOK_RECEIVED_AFTER || "");
if (Number.isNaN(cutoff.getTime())) throw new Error("Configure a valid Outlook received-after cutoff.");
if (!($env.SMARTINBOX_OUTLOOK_MAILBOX_ID || "").trim()) throw new Error("Configure the authorized Outlook mailbox identity.");
return [{ json: { attempt: 1 } }];

const response = $input.first().json;
const body = response.body ?? response;
const expected = String($env.SMARTINBOX_OUTLOOK_MAILBOX_ID || "").trim().toLowerCase();
const actual = String(body.mail || body.userPrincipalName || "").trim().toLowerCase();
return [{ json: { identityVerified: Number(response.statusCode ?? 200) === 200 && !!expected && actual === expected, reason: actual === expected ? null : "mailbox-identity-mismatch" } }];

function retryAfterSeconds(headers) {
  const raw = headers?.['retry-after'] ?? headers?.['Retry-After'] ?? headers?.['RETRY-AFTER'];
  if (raw == null) return null;
  const seconds = Number(raw);
  if (Number.isFinite(seconds) && seconds >= 0) return Math.min(seconds, 60);
  const date = Date.parse(String(raw));
  return Number.isNaN(date) ? null : Math.min(Math.max(0, Math.ceil((date - Date.now()) / 1000)), 60);
}
const attempt = $("Build Outlook Graph Poll Request").first().json.attempt;
const responses = $input.all().map(item => item.json ?? {});
const failed = responses.find(response => Number(response.statusCode ?? 200) !== 200);
if (failed) {
  const statusCode = Number(failed.statusCode ?? 0);
  const retry = (statusCode === 429 || statusCode >= 500 || statusCode === 0) && attempt < 3;
  return [{ json: { graphError: true, statusCode: statusCode || null, retryAfterSeconds: retryAfterSeconds(failed.headers), attempt, retry } }];
}
const messages = responses.flatMap(response => {
  const body = response.body ?? response;
  if (Array.isArray(body)) return body;
  if (Array.isArray(body.value)) return body.value;
  return [];
});
return messages.map((message, index) => ({ json: message, pairedItem: { item: index } }));

